#!/usr/bin/env Rscript
args<-commandArgs(trailingOnly=TRUE);root<-if(length(args))normalizePath(args[[1]])else normalizePath(".")
.libPaths(c(file.path(root,"project","Rlib-4.5"),.libPaths()));suppressPackageStartupMessages(library(data.table))
rel<-function(x)sub(paste0("^",root,"/"),"",normalizePath(x,mustWork=FALSE))
sha<-function(x){if(!length(x))return("");h<-tools::md5sum(character(0));vals<-vapply(x,function(f){raw<-readBin(f,"raw",n=file.info(f)$size);paste(sprintf("%02x",as.integer(openssl::sha256(raw))),collapse="")},character(1));paste(paste0(rel(x),"=",vals),collapse=";")}
paths<-function(pattern){sort(Sys.glob(file.path(root,pattern)))}
bundle<-function(pattern){x<-paths(pattern);paste(rel(x),collapse=";")}
