expand_braces<-function(p){if(!grepl("\\{",p))return(paths(p));pre<-sub("\\{.*$","",p);inside<-sub("^[^{]*\\{([^}]*)\\}.*$","\\1",p);post<-sub("^[^}]*\\}","",p);unlist(lapply(strsplit(inside,",",fixed=TRUE)[[1]],function(z)expand_braces(paste0(pre,z,post))),use.names=FALSE)}
expand_multi<-function(p){if(!nzchar(p))return(character());unique(unlist(lapply(strsplit(p,";",fixed=TRUE)[[1]],expand_braces),use.names=FALSE))}
tab<-rbindlist(lapply(rows,function(r){v<-expand_multi(r$visual);s<-expand_multi(r$source);g<-expand_multi(r$generator);data.table(item_id=r$id,status=r$status,visual_files=paste(rel(v),collapse=";"),visual_sha256=sha(v),source_data_files=paste(rel(s),collapse=";"),source_data_sha256=sha(s),generator_files=if(length(g))paste(rel(g),collapse=";")else r$generator,generator_sha256=sha(g),sample_size_analysis_unit=r$sample,statistical_definition=r$stats)}),fill=TRUE)
outfile<-file.path(root,"project","manuscript","DISPLAY_ITEM_MANIFEST.tsv");fwrite(tab,outfile,sep="\t",quote=TRUE);cat("DISPLAY_ITEM_MANIFEST_COMPLETE",nrow(tab),"rows\n")
